fn fold_left(first: Expr, ops: Vec<(&str, Expr)>) -> Expr {
    ops.into_iter().fold(first, |acc, (op, rhs)| {
        Expr::BinOp(Box::new(acc), op.chars().next().unwrap(), Box::new(rhs))
